<?php

declare(strict_types=1);

namespace App\Module\File;

use Symfony\Component\DependencyInjection\Attribute\Autowire;

/**
 * Local directory outside the web root. Keys are random hex ids generated by the application (never user input);
 * writes are atomic (temporary file + rename) and readable by the application user only.
 */
final class LocalFileStore implements FileStore
{
    public function __construct(
        #[Autowire('%env(resolve:REPORT_STORAGE_DIR)%')]
        private readonly string $dir,
    ) {
    }

    public function put(string $key, string $content): void
    {
        $path = $this->path($key);
        $dir = \dirname($path);
        if (!is_dir($dir) && !@mkdir($dir, 0o700, true) && !is_dir($dir)) {
            throw new \RuntimeException('Cannot create the report storage directory');
        }
        $tmp = $path.'.tmp-'.bin2hex(random_bytes(4));
        if (false === file_put_contents($tmp, $content, \LOCK_EX)) {
            throw new \RuntimeException('Cannot write the report file');
        }
        chmod($tmp, 0o600);
        if (!rename($tmp, $path)) {
            @unlink($tmp);
            throw new \RuntimeException('Cannot store the report file');
        }
    }

    public function get(string $key): string
    {
        $content = is_file($this->path($key)) ? file_get_contents($this->path($key)) : false;

        return false === $content ? throw new \RuntimeException('Report content missing') : $content;
    }

    public function delete(string $key): void
    {
        $path = $this->path($key);
        if (is_file($path)) {
            unlink($path);
        }
    }

    private function path(string $key): string
    {
        if (1 !== preg_match('/^[0-9a-f]{32}$/', $key)) {
            throw new \InvalidArgumentException('Invalid storage key');
        }

        return rtrim($this->dir, '/').'/'.substr($key, 0, 2).'/'.$key.'.csv';
    }
}
